                if g[r][col] != marker:
                    r+=1; continue
                a=r
                while r<h and g[r][col] == marker: r+=1
                if r-a >= 2: runs[col].append((a,r))
        for la,lb in runs[0]:
            for ra,rb in runs[w-1]:
